  city, state, zip_code, website_url, theme_color, primary_color, accent_color,
  welcome_message, scripture_verse, bulletin_title, settings
) values (
  'church-demo', 'demo', 'Riverside Community Church (Demo)',
  'A sample prayer wall to show what PrayerKeeper can do',
  'Non-Denominational', 'Pastor Sam Example', 'demo@example.com', '(555) 010-0000',
  '123 Example Street', 'Springfield', 'USA', null, 'https://prayers.churchwebsitepros.com',
  'teal_pink', '#43b1a4', '#d312b4',
  'This is a demo prayer wall with sample requests and made-up names. Explore it freely; register your church to get your own.',
  'Pray without ceasing. — 1 Thessalonians 5:17',
